  public void ZoomAt(float target,Vector2 pivot){float next=Mathf.Clamp(target,(float)PrestigeBalance.ZoomMin,(float)PrestigeBalance.ZoomMax);float ratio=next/zoom;World.anchoredPosition=pivot-(pivot-World.anchoredPosition)*ratio;zoom=next;World.localScale=Vector3.one*zoom;Clamp();}
  public void Pinch(Vector2 oldA,Vector2 oldB,Vector2 nextA,Vector2 nextB){var before=(oldA+oldB)/2;var after=(nextA+nextB)/2;ZoomAt(zoom*Vector2.Distance(nextA,nextB)/Mathf.Max(1,Vector2.Distance(oldA,oldB)),before);World.anchoredPosition+=after-before;Clamp();blockClickUntil=Time.unscaledTime+.25f;}
  void Clamp(){var p=World.anchoredPosition;float extent=1850*zoom;p.x=Mathf.Clamp(p.x,-extent,extent);p.y=Mathf.Clamp(p.y,-extent,extent);World.anchoredPosition=p;}
